<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useQuasar } from 'quasar'
import { waApi, botApi, unwrap, messageOf, formatDate, sizeText, openWhatsAppSocket } from 'src/services/whatsapp'
import AIProfiles from './AIProfiles.vue'
import InfinitePayPanel from './InfinitePayPanel.vue'
import { apiBaseURL } from 'boot/axios'
const props = defineProps({ tab: String, status: Object }), emit = defineEmits(['refresh', 'status'])
const $q = useQuasar(), busy = ref(false), assets = ref([]), assetPage = ref(1), assetTotal = ref(0), assetSearch = ref(''), assetFile = ref(null), uploadProgress = ref(0), monitor = ref(null), credentials = ref([]), credentialDialog = ref(false), credential = ref({ name: '', description: '', value: '' }), integration = ref({ enabled: false, url: '', events: ['message.received', 'message.sent', 'chat.updated', 'whatsapp.status'], secret: '', inboundSecret: '' }), inbound = ref({}), settings = ref({}), integrationLoaded = ref(false)
const eventOptions = ['message.received', 'message.sent', 'chat.updated', 'whatsapp.status']
const collectSeconds = ref(3), settingsDirty = ref(false), settingsSaving = ref(false)
const retryingPayment = ref('')
async function saveBotSettings() {
  settingsSaving.value = true
  try {
    const { data } = await waApi.put('/bot-settings', { collectWindowMs: Math.round(Number(collectSeconds.value) * 1000) })
    collectSeconds.value = data.collectWindowMs / 1000; settingsDirty.value = false
    $q.notify({ type: 'positive', message: 'Intervalo atualizado para o bot e o simulador.' })
  } catch (error) { fail(error) } finally { settingsSaving.value = false }
}
let timer, liveSocket
const online = computed(() => ['ready', 'online'].includes(props.status?.status))
const qr = computed(() => props.status?.qrCode || props.status?.qr || '')
const connecting = computed(() => ['connecting', 'reconnecting', 'authenticating'].includes(props.status?.status))
const connectionState = computed(() => ({ online: 'Conectado', waiting_qr: 'Aguardando leitura do QR', connecting: 'Abrindo WhatsApp Web', reconnecting: 'Tentando reconectar', authenticating: 'Autenticando', disconnecting: 'Encerrando sessão', auth_required: 'Novo QR necessário', offline: 'Desconectado', error: 'Falha na conexão', disabled: 'Desativado' })[props.status?.status] || props.status?.status || 'Desconectado')
const incomingUrl = computed(() => `${String(apiBaseURL).replace(/\/$/, '')}${inbound.value.endpoint || '/webhooks/whatsapp'}`)
const resources = computed(() => monitor.value?.resources || {})
const percent = (value) => Number.isFinite(value) ? Math.round(value) : '—'
const integer = value => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 0 }).format(Number(value || 0))
const money = (value, currency) => Number.isFinite(Number(value)) ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency, minimumFractionDigits: 2, maximumFractionDigits: 4 }).format(Number(value)) : '—'
const resourceLabel = computed(() => ({ critical: 'Proteção de recursos ativa', elevated: 'Processamento limitado para proteger a sessão', normal: 'Uso normal', unknown: 'Medição indisponível neste ambiente' })[resources.value.level] || 'Monitorando recursos')
function fail(error) { $q.notify({ type: 'negative', message: messageOf(error) }) }
async function connectionAction(action) {
  busy.value = true
  try {
    const result = unwrap(await waApi.post(`/${action === 'reset' ? 'reconnect' : action}`, action === 'disconnect' ? { logout: true } : action === 'reset' ? { resetSession: true } : {}, { timeout: 15000 }))
    emit('status', result); emit('refresh')
    $q.notify({ type: 'info', message: action === 'disconnect' ? 'Encerramento solicitado. Acompanhe o estado da sessão.' : action === 'reset' ? 'Preparando uma nova sessão. Aguarde o QR Code.' : 'Conexão solicitada. Acompanhe o estado abaixo.' })
  } catch (error) { fail(error) } finally { busy.value = false }
}
function resetSession() { $q.dialog({ title: 'Gerar novo QR Code', message: 'Substituir o vínculo atual para conectar novamente? O histórico, os contatos e os arquivos do painel serão preservados.', cancel: true, persistent: true }).onOk(() => connectionAction('reset')) }
function disconnect() { $q.dialog({ title: 'Desconectar WhatsApp', message: 'Esta ação encerra a sessão. Será necessário ler um novo QR Code para retomar o atendimento. Deseja desconectar?', cancel: true, persistent: true }).onOk(() => connectionAction('disconnect')) }
async function loadAssets() { busy.value = true; try { const result = unwrap(await waApi.get('/assets', { params: { q: assetSearch.value, page: assetPage.value, limit: 50 } })); assets.value = result.items || []; assetTotal.value = result.total || assets.value.length } catch (error) { fail(error) } finally { busy.value = false } }
async function uploadAsset(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (file.size > 16 * 1024 * 1024) return fail(new Error('O limite por arquivo é 16 MB.')); busy.value = true; uploadProgress.value = 0; try { const form = new FormData(); form.append('file', file); form.append('permanent', 'true'); await waApi.post('/assets', form, { onUploadProgress: (event) => { uploadProgress.value = event.loaded / (event.total || file.size) } }); await loadAssets(); $q.notify({ type: 'positive', message: 'Arquivo adicionado à biblioteca.' }) } catch (error) { fail(error) } finally { busy.value = false; uploadProgress.value = 0 } }
async function downloadAsset(asset) { try { const { data } = await waApi.get(`/media/${asset._id}`, { responseType: 'blob' }); const url = URL.createObjectURL(data), anchor = document.createElement('a'); anchor.href = url; anchor.download = asset.name || 'arquivo'; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 10000) } catch (error) { fail(error) } }
function removeAsset(asset) { $q.dialog({ title: 'Excluir arquivo', message: `Excluir “${asset.name}” da biblioteca? Arquivos em uso por fluxos e mensagens são protegidos.`, cancel: true }).onOk(async () => { try { await waApi.delete(`/assets/${asset._id}`); loadAssets() } catch (error) { fail(error) } }) }
async function loadBackup() {
  busy.value = true
  try {
    await waApi.post('/history/load'); await loadMonitor()
    $q.notify({ type: 'info', message: 'Carga solicitada. O histórico não dispara o bot nem marca mensagens como não lidas.' })
  } catch (error) { fail(error) } finally { busy.value = false }
}
async function loadMonitor(silent = false) { try { monitor.value = unwrap(await waApi.get('/monitor')); if (!settingsDirty.value) collectSeconds.value = (monitor.value.botSettings?.collectWindowMs ?? 3000) / 1000 } catch (error) { if (!silent) fail(error) } }
function registerDecline(order) {
  $q.dialog({ title: 'Registrar pagamento recusado', message: `Confirme no painel da InfinitePay que o pedido ${order.orderNsu} foi recusado. Isso avisará o comprador e executará a saída “Pagamento recusado” do fluxo.`, cancel: true, persistent: true }).onOk(async () => {
    try { await waApi.post(`/infinitepay/orders/${encodeURIComponent(order.orderNsu)}/decline`); await loadMonitor(); $q.notify({ type: 'positive', message: 'Recusa registrada e notificações adicionadas à fila.' }) } catch (cause) { fail(cause) }
  })
}
async function retryPayment(event) {
  if (!event?.orderNsu || retryingPayment.value) return
  retryingPayment.value = event.orderNsu
  try {
    await waApi.post(`/infinitepay/orders/${encodeURIComponent(event.orderNsu)}/retry`)
    await loadMonitor()
    $q.notify({ type: 'positive', message: 'Pagamento revalidado. Confira o estado no monitoramento.' })
  } catch (cause) { fail(cause) }
  finally { retryingPayment.value = '' }
}
async function loadIntegrations() {
  busy.value = true
  const results = await Promise.allSettled([waApi.get('/integrations'), botApi.get('/credentials'), botApi.get('/settings')])
  if (results[0].status === 'fulfilled') { const result = unwrap(results[0].value); integration.value = { ...integration.value, ...result.webhook, secret: '', inboundSecret: '' }; inbound.value = result.inbound || {}; integrationLoaded.value = true } else fail(results[0].reason)
  if (results[1].status === 'fulfilled') credentials.value = unwrap(results[1].value).items || []; else fail(results[1].reason)
  if (results[2].status === 'fulfilled') settings.value = unwrap(results[2].value).settings || {}; else fail(results[2].reason)
  busy.value = false
}
async function saveIntegrations() { busy.value = true; try { await waApi.put('/integrations', { enabled: integration.value.enabled, url: integration.value.url, events: integration.value.events, ...(integration.value.secret ? { secret: integration.value.secret } : {}), ...(integration.value.inboundSecret ? { inboundSecret: integration.value.inboundSecret } : {}) }); $q.notify({ type: 'positive', message: 'Integrações atualizadas.' }); await loadIntegrations() } catch (error) { fail(error) } finally { busy.value = false } }
function editCredential(value) { credential.value = value ? { ...value, value: '' } : { name: '', description: '', value: '' }; credentialDialog.value = true }
async function saveCredential() { busy.value = true; try { const body = { name: credential.value.name, description: credential.value.description, ...(credential.value.value ? { value: credential.value.value } : {}) }; if (credential.value._id) await botApi.put(`/credentials/${credential.value._id}`, body); else await botApi.post('/credentials', body); credentialDialog.value = false; credential.value = { name: '', description: '', value: '' }; await loadIntegrations() } catch (error) { fail(error) } finally { busy.value = false } }
function removeCredential(value) { $q.dialog({ title: 'Excluir credencial', message: `Remover ${value.name}? Os fluxos que utilizam esta credencial precisarão ser atualizados.`, cancel: true }).onOk(async () => { try { await botApi.delete(`/credentials/${value._id}`); await loadIntegrations() } catch (error) { fail(error) } }) }
function safeDetails(value) { return typeof value === 'string' ? value : JSON.stringify(value || {}) }
onMounted(() => { if (props.tab === 'assets') loadAssets(); if (props.tab === 'integrations') loadIntegrations(); if (props.tab === 'monitor') { loadMonitor(); timer = setInterval(() => { if (!document.hidden) loadMonitor(true) }, 15000); liveSocket = openWhatsAppSocket(); liveSocket.on('infinitepay.event', () => loadMonitor(true)); liveSocket.on('infinitepay.order', () => loadMonitor(true)) } })
onBeforeUnmount(() => { clearInterval(timer); liveSocket?.disconnect() })
</script>

<template>
  <section class="wa-tools">
    <template v-if="tab === 'connection'">
      <header><div><span class="wa-eyebrow">SESSÃO DO WHATSAPP</span><h2>Conexão</h2><p>Uma sessão compartilhada pela equipe, com identificação individual em cada atendimento.</p></div><q-badge :color="online ? 'teal-7' : 'amber-9'">{{ connectionState }}</q-badge></header>
      <div class="wa-connection-grid"><article class="wa-tool-card wa-qr"><img v-if="qr && !online" :src="qr" alt="QR Code para conectar o WhatsApp" /><q-spinner v-else-if="connecting" color="teal-3" size="76px" /><q-icon v-else :name="online ? 'mdi-whatsapp' : 'mdi-qrcode-scan'" :color="online ? 'teal-3' : 'blue-grey-4'" size="96px" /><h3>{{ online ? 'Tudo pronto para atender' : qr ? 'Escaneie para conectar' : connecting ? 'Preparando a conexão…' : 'Conecte o WhatsApp da AitoSoftwares' }}</h3><p v-if="qr && !online">No celular: WhatsApp → Dispositivos conectados → Conectar dispositivo.</p><p v-else-if="online">{{ status?.connectedPhone || status?.phone || 'A sessão está disponível para os administradores.' }}</p><p v-else-if="connecting">Aguardando o WhatsApp Web carregar e disponibilizar o QR Code. Você pode interromper a tentativa com Desconectar.</p><p v-else>A sessão é preservada entre reinícios. Um novo QR Code só é solicitado quando a autenticação precisa ser renovada.</p><q-btn v-if="!online" color="teal-6" no-caps :label="qr ? 'Atualizar estado' : 'Conectar WhatsApp'" :loading="busy" @click="qr ? emit('refresh') : connectionAction('connect')" /></article><article class="wa-tool-card"><h3>Estado da sessão</h3><dl><div><dt>Status</dt><dd>{{ connectionState }}</dd></div><div><dt>Última conexão</dt><dd>{{ formatDate(status?.lastConnectedAt || status?.connectedAt) || 'Ainda não registrada' }}</dd></div><div><dt>Última desconexão</dt><dd>{{ formatDate(status?.lastDisconnectedAt || status?.disconnectedAt) || 'Nenhuma registrada' }}</dd></div></dl><p v-if="status?.lastError || status?.error" class="wa-warning">{{ status.lastError || status.error }}</p><p class="wa-help">Use Reconectar para recuperar a sessão. Se removeu o dispositivo pelo celular, use Gerar novo QR. Desconectar interrompe a tentativa e limpa o vínculo local.</p><div class="wa-actions"><q-btn outline no-caps icon="mdi-refresh" label="Reconectar" :loading="busy" @click="connectionAction('reconnect')" /><q-btn outline no-caps icon="mdi-qrcode-plus" label="Gerar novo QR" :disable="busy" @click="resetSession" /><q-btn flat no-caps color="red-3" label="Desconectar sessão" :disable="busy" @click="disconnect" /></div></article></div>
    </template>

    <template v-if="tab === 'assets'">
      <header><div><span class="wa-eyebrow">BIBLIOTECA COMPARTILHADA</span><h2>Arquivos</h2><p>Imagens, áudios, vídeos e documentos para mensagens e cards do bot. Até 16 MB por arquivo.</p></div><q-btn color="teal-6" no-caps icon="mdi-upload" label="Adicionar arquivo" :loading="busy" @click="assetFile.click()" /><input ref="assetFile" type="file" hidden @change="uploadAsset" /></header>
      <q-input v-model="assetSearch" outlined dense clearable placeholder="Buscar arquivo" @keyup.enter="assetPage = 1; loadAssets()"><template #append><q-btn flat round dense icon="mdi-magnify" aria-label="Buscar" @click="assetPage = 1; loadAssets()" /></template></q-input><q-linear-progress v-if="busy" :value="uploadProgress" :indeterminate="!uploadProgress" color="teal-3" class="q-mt-sm" />
      <div class="wa-assets"><article v-for="asset in assets" :key="asset._id"><q-icon :name="asset.mime?.startsWith('image/') ? 'mdi-image-outline' : asset.mime?.startsWith('audio/') ? 'mdi-music-note-outline' : asset.mime?.startsWith('video/') ? 'mdi-video-outline' : 'mdi-file-document-outline'" size="30px" /><div><strong>{{ asset.name }}</strong><small>{{ sizeText(asset.size) }} · {{ formatDate(asset.createdAt, true) }}</small></div><q-btn flat round dense icon="mdi-download" aria-label="Baixar arquivo" @click="downloadAsset(asset)" /><q-btn flat round dense icon="mdi-delete-outline" color="red-3" aria-label="Excluir arquivo" @click="removeAsset(asset)" /></article></div><p v-if="!busy && !assets.length" class="wa-empty">Nenhum arquivo na biblioteca.</p><q-pagination v-if="assetTotal > 50" v-model="assetPage" :max="Math.ceil(assetTotal / 50)" :max-pages="6" color="teal-4" @update:model-value="loadAssets" />
    </template>

    <template v-if="tab === 'integrations'">
      <header><div><span class="wa-eyebrow">APIS E WEBHOOKS</span><h2>Integrações</h2><p>Conecte o atendimento aos seus sistemas e guarde as credenciais utilizadas pelos fluxos.</p></div><q-btn flat round icon="mdi-refresh" aria-label="Atualizar integrações" :loading="busy" @click="loadIntegrations" /></header>
      <AIProfiles />
      <InfinitePayPanel />
      <div class="wa-integrations-grid"><article class="wa-tool-card"><h3>Notificações de saída</h3><q-toggle v-model="integration.enabled" color="teal-4" label="Enviar eventos para um webhook" /><q-input v-model="integration.url" outlined label="URL HTTPS do webhook" placeholder="https://seusistema.com/webhook" class="q-my-md" /><q-select v-model="integration.events" outlined multiple use-chips :options="eventOptions" label="Eventos enviados" class="q-mb-md" /><q-input v-model="integration.secret" outlined type="password" autocomplete="new-password" label="Segredo de assinatura" :hint="integration.hasSecret ? 'Já configurado. Deixe vazio para manter.' : 'Defina uma chave forte para validar a assinatura dos eventos.'" /><h3 class="q-mt-xl">Entrada de eventos</h3><p class="wa-help">Receba mensagens de integrações e encaminhe para o fluxo ativo.</p><code class="wa-endpoint">POST {{ incomingUrl }}</code><q-input v-model="integration.inboundSecret" outlined type="password" autocomplete="new-password" label="Segredo do webhook de entrada" :hint="inbound.hasSecret ? 'Já configurado. Deixe vazio para manter.' : 'Defina uma chave para habilitar a entrada.'" class="q-mt-md" /><p class="wa-help">Assinatura: HMAC SHA-256 de <code>timestamp + &quot;.&quot; + JSON original</code>, com timestamp em segundos. Envie <code>eventId</code>, <code>phone</code>, <code>name</code> e <code>text</code> no JSON. Assine com HMAC SHA-256 e os cabeçalhos <code>x-aito-signature</code> e <code>x-aito-timestamp</code>.</p><q-btn color="teal-6" no-caps label="Salvar integrações" :loading="busy" :disable="!integrationLoaded" @click="saveIntegrations" /></article>
      <article class="wa-tool-card"><div class="wa-card-title"><h3>Credenciais dos fluxos</h3><q-btn flat round icon="mdi-plus" aria-label="Adicionar credencial" @click="editCredential()" /></div><p class="wa-help">Use <code v-pre>{{secret.NOME}}</code> nos cabeçalhos e campos das ações HTTP. Os valores são protegidos e não são exibidos após salvar.</p><div v-for="item in credentials" :key="item._id" class="wa-credential"><div><strong>{{ item.name }}</strong><small>{{ item.description || 'Credencial protegida' }}</small></div><q-btn flat round dense icon="mdi-pencil-outline" aria-label="Editar credencial" @click="editCredential(item)" /><q-btn flat round dense icon="mdi-delete-outline" color="red-3" aria-label="Excluir credencial" @click="removeCredential(item)" /></div><p v-if="!credentials.length" class="wa-empty">Nenhuma credencial cadastrada.</p><h3 class="q-mt-xl">Destinos permitidos</h3><p class="wa-help">As ações HTTP só acessam domínios HTTPS autorizados na configuração do servidor.</p><q-chip v-for="host in settings.httpAllowedHosts || []" :key="host" color="teal-10" text-color="teal-2" dense>{{ host }}</q-chip><p v-if="!settings.httpAllowedHosts?.length" class="wa-warning">Nenhum domínio autorizado ainda. Configure os destinos da integração antes de ativar ações HTTP.</p></article></div>
      <q-dialog v-model="credentialDialog"><q-card class="wa-credential-dialog"><q-card-section><h3 class="text-h6 q-mt-none">{{ credential._id ? 'Editar credencial' : 'Nova credencial' }}</h3><q-input v-model="credential.name" dark outlined label="Nome" placeholder="CRM_TOKEN" :disable="!!credential._id" class="q-mb-md" /><q-input v-model="credential.description" dark outlined label="Descrição" class="q-mb-md" /><q-input v-model="credential.value" dark outlined type="password" autocomplete="new-password" label="Valor secreto" :hint="credential._id ? 'Deixe vazio para manter o valor atual.' : 'O valor não será exibido novamente.'" /></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" v-close-popup /><q-btn color="teal-7" no-caps label="Salvar" :loading="busy" :disable="!credential.name || (!credential._id && !credential.value)" @click="saveCredential" /></q-card-actions></q-card></q-dialog>
    </template>

    <template v-if="tab === 'monitor'">
      <header><div><span class="wa-eyebrow">SAÚDE DO ATENDIMENTO</span><h2>Monitoramento</h2><p>Uso de recursos, fila de mensagens, administradores conectados e eventos recentes. Atualiza a cada 15 segundos.</p></div><q-btn flat round icon="mdi-refresh" aria-label="Atualizar monitoramento" @click="loadMonitor()" /></header>
      <div v-if="!monitor" class="wa-empty"><q-spinner color="teal-3" size="30px" /></div>
      <template v-else><div class="wa-metrics"><article><span>CPU</span><strong>{{ percent(resources.cpuPercent) }}<small>%</small></strong><q-linear-progress :value="Math.min(1, (resources.cpuPercent || 0) / 100)" :color="resources.cpuPercent > 80 ? 'amber-5' : 'teal-4'" rounded /><p>{{ resourceLabel }}</p></article><article><span>Memória</span><strong>{{ percent(resources.memoryPercent) }}<small>%</small></strong><q-linear-progress :value="Math.min(1, (resources.memoryPercent || 0) / 100)" :color="resources.memoryPercent > 80 ? 'amber-5' : 'teal-4'" rounded /><p>{{ Math.round(resources.memoryMb ?? resources.nodeRssMb ?? 0) }} / {{ Math.round(resources.memoryLimitMb || 0) }} MB</p></article><article><span>Fila de envios</span><strong>{{ monitor.queue?.queued || 0 }}</strong><p>{{ monitor.queue?.processing || 0 }} processando · {{ monitor.queue?.failed || 0 }} falhas · {{ monitor.queue?.uncertain || 0 }} sem confirmação</p></article><article><span>Filas pesadas</span><strong class="wa-text-metric">{{ (monitor.aiQueue?.active || 0) + (monitor.aiQueue?.waiting || 0) }}</strong><p>IA: {{ monitor.aiQueue?.active || 0 }} processando, {{ monitor.aiQueue?.waiting || 0 }} aguardando · mídia: {{ monitor.mediaRecovery?.active ? 'recuperando' : 'livre' }}</p></article><article><span>Redis</span><strong class="wa-text-metric">{{ monitor.redis?.connected ? 'Conectado' : monitor.redis?.configured ? 'Reconectando' : 'Não configurado' }}</strong><p>Arquivos: {{ sizeText(monitor.storage?.bytes) }} / {{ sizeText(monitor.storage?.limitBytes) }}</p></article></div>
      <article class="wa-tool-card q-my-lg payment-monitor"><div class="wa-card-title"><div><span class="wa-eyebrow">INFINITEPAY</span><h3>Links e pagamentos</h3></div><q-icon name="mdi-credit-card-check-outline" size="28px" color="teal-3" /></div><div class="payment-banner"><div><strong>{{ monitor.infinitepay?.counts?.reduce((n, row) => n + row.count, 0) || 0 }}</strong><span>links gerados</span></div><div><strong>{{ monitor.infinitepay?.counts?.find(row => row._id === 'pending')?.count || 0 }}</strong><span>aguardando</span></div><div><strong>{{ monitor.infinitepay?.counts?.find(row => row._id === 'paid')?.count || 0 }}</strong><span>aprovados</span></div><div><strong>{{ monitor.infinitepay?.counts?.find(row => row._id === 'declined')?.count || 0 }}</strong><span>recusados confirmados</span></div></div><p class="wa-help">A InfinitePay documenta notificações de aprovação. Tentativas não concluídas permanecem pendentes; confirme a recusa no painel da InfinitePay antes de registrá-la aqui.</p><div class="payment-orders"><article v-for="order in monitor.infinitepay?.orders || []" :key="order.orderNsu"><div><strong>{{ order.chatId?.name || order.chatId?.phone || 'Contato removido' }}</strong><small>{{ order.chatId?.phone }} · {{ formatDate(order.createdAt) }} · {{ order.orderNsu }}</small></div><q-badge :color="order.status === 'paid' ? 'teal-7' : order.status === 'declined' ? 'red-8' : 'amber-9'">{{ order.status === 'paid' ? 'Aprovado' : order.status === 'declined' ? 'Recusado' : order.status === 'creating' ? 'Preparando' : 'Aguardando' }}</q-badge><b>{{ money(order.amountCents / 100, 'BRL') }}</b><a v-if="order.checkoutUrl" :href="order.checkoutUrl" target="_blank" rel="noopener noreferrer">Link ↗</a><a v-if="order.receiptUrl" :href="order.receiptUrl" target="_blank" rel="noopener noreferrer">Comprovante ↗</a><q-btn v-if="order.status === 'pending'" flat dense no-caps color="amber-3" label="Registrar recusa" @click="registerDecline(order)" /></article><p v-if="!monitor.infinitepay?.orders?.length" class="wa-help">Nenhum link gerado ainda.</p></div><details class="payment-json"><summary>Eventos JSON recebidos da InfinitePay ({{ monitor.infinitepay?.events?.length || 0 }})</summary><article v-for="event in monitor.infinitepay?.events || []" :key="event._id"><strong>{{ formatDate(event.createdAt) }} · {{ event.orderNsu }} · {{ event.state }}</strong><pre>{{ JSON.stringify(event.payload, null, 2) }}</pre><p v-if="event.error">{{ event.error }}</p><q-btn v-if="event.state === 'failed' && event.orderNsu" outline dense no-caps color="teal-3" label="Rever pagamento" :loading="retryingPayment === event.orderNsu" @click="retryPayment(event)" /></article></details></article>
      <article class="wa-tool-card q-my-lg"><div class="wa-card-title"><h3>Consumo da IA · últimos {{ monitor.aiUsage?.periodDays || 7 }} dias</h3><q-icon name="mdi-currency-usd" size="24px" color="teal-3" /></div><div v-if="monitor.aiUsage?.error" class="wa-warning">Não foi possível calcular o consumo: {{ monitor.aiUsage.error }}</div><template v-else><div class="wa-ai-cost"><div><span>Tokens</span><strong>{{ integer(monitor.aiUsage?.totals?.totalTokens) }}</strong><small>{{ integer(monitor.aiUsage?.totals?.inputTokens) }} entrada · {{ integer(monitor.aiUsage?.totals?.outputTokens) }} saída</small></div><div><span>Estimativa em dólar</span><strong>{{ money(monitor.aiUsage?.totals?.estimatedUsd, 'USD') }}</strong><small>{{ monitor.aiUsage?.totals?.requests || 0 }} solicitação(ões) · {{ monitor.aiUsage?.totals?.images || 0 }} imagem(ns)</small></div><div><span>Estimativa em real</span><strong>{{ money(monitor.aiUsage?.totals?.estimatedBrl, 'BRL') }}</strong><small v-if="monitor.aiUsage?.exchange?.rate">US$ 1 ≈ R$ {{ Number(monitor.aiUsage.exchange.rate).toFixed(4).replace('.', ',') }}</small><small v-else>Cotação ainda indisponível</small></div></div><div v-if="monitor.aiUsage?.byModel?.length" class="wa-ai-models"><div v-for="row in monitor.aiUsage.byModel" :key="row.model"><strong>{{ row.model }}</strong><span>{{ integer(row.totalTokens) }} tokens</span><span>{{ money(row.estimatedUsd, 'USD') }}</span><span>{{ money(row.estimatedBrl, 'BRL') }}</span></div></div><p class="wa-help">A cotação é atualizada semanalmente pelo Banco Central do Brasil. Tokens vêm do uso informado pela OpenAI; valores são aproximados e podem incluir estimativas para imagens e ferramentas. Última cotação: {{ formatDate(monitor.aiUsage?.exchange?.fetchedAt) || 'buscando…' }}.</p></template></article>
      <article class="wa-tool-card q-my-lg"><h3>Agrupamento de mensagens</h3><p class="wa-help">Tempo de espera após a última mensagem do cliente, aplicado ao bot e ao simulador.</p><q-input v-model.number="collectSeconds" type="number" min="0.2" max="15" step="0.1" outlined dense label="Intervalo (segundos)" style="max-width:260px" @update:model-value="settingsDirty = true" /><q-btn class="q-mt-md" no-caps color="teal-7" label="Salvar intervalo" :loading="settingsSaving" :disable="!settingsDirty || !Number.isFinite(collectSeconds) || collectSeconds < 0.2 || collectSeconds > 15" @click="saveBotSettings" /></article>
      <article class="wa-tool-card q-my-lg"><h3>Histórico do WhatsApp</h3><p class="wa-help">O histórico antigo não é importado automaticamente. Carregar backup busca as mensagens recentes disponíveis no WhatsApp, sem executar fluxos ou baixar anexos. Limite: {{ monitor.status?.historyLimit?.chats || 20 }} conversas e {{ monitor.status?.historyLimit?.messages || 20 }} mensagens por conversa.</p><q-btn no-caps color="teal-7" icon="mdi-backup-restore" label="Carregar backup" :loading="busy || monitor.status?.historySyncing" :disable="!online" @click="loadBackup" /><p v-if="monitor.status?.historySyncing" class="wa-help">Carregando… {{ monitor.status?.historyLoaded || 0 }} mensagens verificadas.</p><p v-else-if="monitor.status?.historySyncedAt" class="wa-help">Última carga: {{ formatDate(monitor.status.historySyncedAt) }}</p><p v-if="monitor.status?.historyError" class="text-negative">{{ monitor.status.historyError }}</p></article>
      <article class="wa-tool-card q-my-lg"><h3>Equipe conectada</h3><div class="wa-presence"><span v-for="person in monitor.presence || []" :key="person.id"><q-icon name="mdi-account-circle-outline" />{{ person.name }}<small>{{ person.connections }} conexão(ões)</small></span><p v-if="!monitor.presence?.length" class="wa-help">Nenhuma conexão ativa no painel.</p></div></article>
      <article class="wa-tool-card"><h3>Eventos recentes</h3><div class="wa-log-list"><article v-for="(log, index) in monitor.logs || []" :key="log._id || index"><time>{{ formatDate(log.createdAt) }}</time><q-badge :color="log.level === 'error' ? 'red-9' : log.level === 'warn' ? 'amber-9' : 'blue-grey-7'">{{ log.level }}</q-badge><strong>{{ log.event }}</strong><p>{{ safeDetails(log.details) }}</p></article><p v-if="!monitor.logs?.length" class="wa-help">Nenhum evento registrado.</p></div></article></template>
    </template>
  </section>
</template>

